"""Maakt filosofie/toets/data.json (leer.js) en de afbeeldingen uit de foto's van de reader 'Wat is filosofie?'.
Gebruik: python make_data.py <repo-map> <map met foto's>"""
import json, sys
from PIL import Image, ImageOps
ROOT, SRC = sys.argv[1], sys.argv[2]
MOD = f"{ROOT}/filosofie/toets"
C = True
PH = {"voorblad": "153900", "vragen": "153908", "op1": "153922", "voor": "154010", "op2": "154021", "op3": "154030", "hist": "154039", "soc": "154046", "histb": "154055", "dialoog": "154145"}
