for k, p in PH.items():
    im = ImageOps.exif_transpose(Image.open(f"{SRC}/20261101_{p}.jpg")).convert("RGB")
    full = im.copy(); full.thumbnail((1600, 1600)); full.save(f"{MOD}/bronnen/{k}.jpg", quality=78, optimize=True)
    if k == "hist":
        f = im.width / 1200; im.crop((int(790 * f), int(840 * f), int(1075 * f), int(1415 * f))).resize((570, 1150)).save(f"{MOD}/fig/avocado.jpg", quality=82)
    if k == "dialoog": full.save(f"{MOD}/fig/dialoog.jpg", quality=80)
def b(*ks): return [{"src": f"bronnen/{k}.jpg", "cap": CAP[k]} for k in ks]
